namespace Invoicing;

/// <summary>Resolves the VAT due for a net amount given account and jurisdiction.</summary>
public sealed class VatResolver
{
    public decimal Resolve(Account account, decimal net, string countryCode)
    {
        if (net <= 0m)
            return 0m;

        var standardRate = GetStandardRate(countryCode);
        var adjustedRate = AdjustRate(standardRate, account.Kind, net);
        return net * adjustedRate;
    }

    private static decimal GetStandardRate(string countryCode) => countryCode switch
    {
        "GB" => 0.20m,
        "DE" => 0.19m,
        "FR" => 0.20m,
        "IE" => 0.23m,
        _ => 0m
    };

    private static decimal AdjustRate(decimal rate, AccountKind accountKind, decimal net)
    {
        if (accountKind == AccountKind.Government)
            return 0m;

        if (accountKind == AccountKind.Business && net > 10000m)
            rate *= 0.5m;

        return rate > 0m && net > 100000m
            ? Math.Min(rate, 0.15m)
            : rate;
    }
}
